// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---

// Web defaults include the default reflection-based resolver,
// so GetTypeInfo<T> will resolve any public type automatically.
var webOptions = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> personInfo = webOptions.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person>() -> Type: {personInfo.Type.Name}, Kind: {personInfo.Kind}");

// Use the typed metadata to serialize
string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing ---

// Create options with a source-gen context that only knows about Person.
var strictOptions = new JsonSerializerOptions();
strictOptions.TypeInfoResolverChain.Add(DemoContext.Default);

// Person IS in the context → should succeed
if (strictOptions.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? found))
    Console.WriteLine($"TryGetTypeInfo<Person>() succeeded: {found!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<Person>() returned false (unexpected)");

// Order is NOT in the context → should return false, no exception
if (strictOptions.TryGetTypeInfo<Order>(out JsonTypeInfo<Order>? notFound))
    Console.WriteLine($"TryGetTypeInfo<Order>() succeeded (unexpected): {notFound!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<Order>() returned false — type not available (expected)");

// --- Types ---

public record Person(string Name, int Age);
public record Order(int Id, decimal Total);

// Source-gen context that only resolves Person
[JsonSerializable(typeof(Person))]
public partial class DemoContext : JsonSerializerContext;

